from pathlib import Path
from collections import Counter
from rdkit import Chem
import numpy as np
lines=Path('opt/xtbopt.xyz').read_text().splitlines(); n=int(lines[0]); atoms=[l.split()[0] for l in lines[2:]]; p=np.array([[float(x) for x in l.split()[1:]] for l in lines[2:]])
assert n==len(p)==120 and np.isfinite(p).all()
print('Composition:',dict(Counter(atoms)))
m=Chem.AddHs(Chem.MolFromSmiles('P(C1CCCCC1)(C1CCCCC1)C1CCCCC1'))
bonds=[]
for off in [16,68]:
 for b in m.GetBonds(): bonds.append((b.GetBeginAtomIdx()+off,b.GetEndAtomIdx()+off))
bonds += [(0,i) for i in [1,2,3,16,68]]+[(3,4),(3,10)]
bonds += [(4+i,4+(i+1)%6) for i in range(6)]+[(5+i,11+i) for i in range(5)]
print('Ligand bond lengths by elements:')
types={}
for i,j in bonds:
 k='-'.join(sorted([atoms[i],atoms[j]])); types.setdefault(k,[]).append(np.linalg.norm(p[i]-p[j]))
for k,v in types.items():print(k,round(min(v),3),round(max(v),3))
bs={tuple(sorted(b)) for b in bonds}
clashes=[]
for i in range(n):
 for j in range(i):
  if (j,i) not in bs and np.linalg.norm(p[i]-p[j])<1.25:clashes.append((j+1,i+1,np.linalg.norm(p[i]-p[j])))
print('Unbonded distances < 1.25 A:',clashes)
lines[1]='Grubbs first-generation catalyst: RuCl2(PCy3)2(=CHPh); explicit H; angstrom'
Path('answer.xyz').write_text('\n'.join(lines)+'\n')
print('answer.xyz exists:',Path('answer.xyz').is_file())
